import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.LevelEvent{EventType: packet.LevelEventStartBlockCracking, Position: mgl32.Vec3{1, 2, 3}, EventData: -1}
START_BLOCK_CRACKING = bytes.fromhex("a0380000803f000000400000404001")

# generated by gophertunnel b8bd735:
# packet.LevelEvent{EventType: -1, Position: mgl32.Vec3{}, EventData: 300}
NEGATIVE_EVENT = bytes.fromhex("01000000000000000000000000d804")

# generated by gophertunnel b8bd735:
# packet.LevelEvent{EventType: packet.LevelEventParticleLegacyEvent + 1, Position: mgl32.Vec3{}, EventData: 0}
PAST_LAST_NAMED = bytes.fromhex("82800200000000000000000000000000")

GOLDENS = [
    pytest.param(
        v2225.LevelEventPacket(event_id=3600, pos=v2225.Vec3(x=1.0, y=2.0, z=3.0), data=-1),
        START_BLOCK_CRACKING,
        id="start-block-cracking",
    ),
    pytest.param(v2225.LevelEventPacket(event_id=-1, data=300), NEGATIVE_EVENT, id="negative-event-id"),
    pytest.param(v2225.LevelEventPacket(event_id=16385), PAST_LAST_NAMED, id="event-id-past-last-named"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_level_event_is_packet_25(version):
    assert version.PACKETS[25] is version.LevelEventPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_level_event_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_level_event_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
